    w = len(grid[0]) if h else 0

    marker_colors = {2, 3}
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    visited = [[False] * w for _ in range(h)]
    components = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                stack = [(r, c)]
                visited[r][c] = True
                cells = []
                while stack:
                    x, y = stack.pop()
                    cells.append((x, y, grid[x][y]))
                    for dx, dy in dirs:
                        nx, ny = x + dx, y + dy
                        if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] != 0 and not visited[nx][ny]:
                            visited[nx][ny] = True
                            stack.append((nx, ny))
                components.append(cells)

    # For each marker color, find the exemplar component:
    # a component containing that marker and at least one other nonzero color.
    exemplars = {}
    targets = {2: [], 3: []}

    for comp in components:
        vals = [v for _, _, v in comp]
        colors = set(vals)
        markers_in_comp = [m for m in marker_colors if m in colors]

        for m in markers_in_comp:
            marker_cells = [(r, c) for r, c, v in comp if v == m]
            if len(colors) > 1:
                # Exemplar
                mr, mc = marker_cells[0]
                fill_cells = [(r, c, v) for r, c, v in comp if v != m]
                exemplars[m] = (mr, mc, fill_cells)
            else:
                # Isolated target(s)
                for mr, mc in marker_cells:
                    targets[m].append((mr, mc))

    out = [row[:] for row in grid]

    for m, tlist in targets.items():
        if m not in exemplars:
            continue

        mr, mc, fill_cells = exemplars[m]
        offsets = [(r - mr, c - mc, v) for r, c, v in fill_cells]

        for tr, tc in tlist:
            for dr, dc, v in offsets:
                # Marker 2 copies a horizontally mirrored version.
                if m == 2:
                    nr, nc = tr + dr, tc - dc
                else:
                    nr, nc = tr + dr, tc + dc
                if 0 <= nr < h and 0 <= nc < w and out[nr][nc] == 0:
                    out[nr][nc] = v

    return out

